<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const card = getPopoverContext(); function attach() { const key = (event: KeyboardEvent) => { if (event.key === 'Escape') card.setOpen(false, 'escape-key', event); }; document.addEventListener('keydown', key); return () => document.removeEventListener('keydown', key); }</script>{#if card.open}<div bind:this={ref} {...rest} id={card.popupId} data-open="" data-side={card.side} data-align={card.align} {@attach attach}>{@render children?.()}</div>{/if}
